responseSchemaJson:
{
  "type": "object",
  "description": "小说总结大师的核心数据结构。仅用于生成纯粹的章节总结。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "summaryOutput": {
      "type": "object",
      "description": "包含章节的短句梗概和详细总结。",
      "properties": {
        "shortSummary": {
          "type": "string",
          "description": "极简的标题式短句，概括本章核心事件。用于替换目录标题。标题无主语。"
        },
        "detailedSummary": {
          "type": "string",
          "description": "详细的剧情回顾，包含关键细节。"
        }
      },
      "required": [
        "shortSummary",
        "detailedSummary"
      ],
      "propertyOrdering": [
        "shortSummary",
        "detailedSummary"
      ]
    },
    "test": {
      "type": "object",
      "description": "[模块二：测试] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "summaryOutput",
    "test"
  ],
  "propertyOrdering": [
    "summaryOutput",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
return {
    shortSummary: data.summaryOutput.shortSummary.replace(/【.*?】[:：]?\s*/g, '').trim(),
    detailedSummary: data.summaryOutput.detailedSummary.replace(/【.*?】[:：]?\s*/g, '').trim()
};
